import{_ as n,o as s,c as e,ai as t}from"./chunks/framework.BxxKhjs3.js";const r="/pub-blog/assets/sdfds.BpXx5nxR.jpg",i="/pub-blog/assets/image-20250901230046423.DFpmQEZp.png",o="/pub-blog/assets/image-20250901230815015.D_T2eLs_.png",p="/pub-blog/assets/image-20250901230828030.TBSSX1Ns.png",l="/pub-blog/assets/image-20250901230837430.CSCCmfXC.png",m="/pub-blog/assets/image-20250901230546619.D41_UGpP.png",g="/pub-blog/assets/image-20250901230608827.acudid4A.png",c="/pub-blog/assets/image-20250901230902442.B73-Pt_y.png",d="/pub-blog/assets/PixPin_2025-09-01_23-10-11.iFrTdqZ1.gif",h="/pub-blog/assets/zhiuik.DawCvQwx.png",b="/pub-blog/assets/image-20250822223258675.CJHnmYEl.png",u="/pub-blog/assets/wanshaoweixin.DWzIcicW.jpg",k=JSON.parse('{"title":"HarmonyOS 鸿蒙应用开发  AI 的 bug AI来修复","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS 鸿蒙应用开发  AI的bug AI来修复/HarmonyOS 鸿蒙应用开发  AI的bug AI来修复.md","filePath":"鸿蒙开发技巧/HarmonyOS 鸿蒙应用开发  AI的bug AI来修复/HarmonyOS 鸿蒙应用开发  AI的bug AI来修复.md","lastUpdated":1757677612000,"__rawMarkdown":"# HarmonyOS 鸿蒙应用开发  AI 的 bug AI来修复\\n\\n## 前言\\n\\n最近由于开发鸿蒙应用存在巨大的红利，我一直在尝试使用AI工具提效功能开发。不过由于鸿蒙应用更新实在太快，一些AI编码工具稍有不慎，就会在功能实现上绕来绕去，始终无法完美解决。\\n\\n![](assets/sdfds.jpg)\\n\\n\\n\\n## 什么bug\\n\\n比如，我这会想要实现一个简单的阅读进度功能，它的原理是**根据当前页面滚动的距离**除以**页面可以滚动的最大的距离**，从而得出阅读**进度的百分比**\\n\\n```\\n阅读进度的百分比 = 当前页面滚动的距离  /  页面可以滚动最大的距离\\n```\\n\\n这部分代码在HarmonyOS中，结合AI工具实现的话， AI编辑工具死活不知道如何获取页面最大的距离，这个也怪它，要知道鸿蒙开发官网的文档都不是服务器渲染的，也就是你直接给ai一个网址，它是无法直接读出里面具体的代码的。\\n\\n![](assets/image-20250901230046423.png)\\n\\n然后我的AI就是一直乱输出代码了，甚至做出了假设页面最大滚动距离为 1500 的**离谱操作**。\\n\\n![](assets/image-20250901230815015.png)\\n\\n---\\n\\n![](assets/image-20250901230828030.png)\\n\\n---\\n\\n![](assets/image-20250901230837430.png)\\n\\n---\\n\\n\\n\\n\\n\\n## 解决方案\\n\\n针对这个情况，解决思路如下：\\n\\n1. 直接向AI工具提供关键代码，并清晰描述问题\\n2. 但要实现这一点，首先需要知道正确的关键代码是什么\\n\\n关键在于使用另一个AI工具——**ima 鸿蒙应用开发知识库**。这是我基于鸿蒙应用API20搭建的知识库，你可以通过自然语言查询获取信息。由于我提前导入了鸿蒙官网1万多个API20文档，它给出的答案相对准确，我最终就是基于它提供的代码完成了需求。\\n\\n![](assets/image-20250901230546619.png)\\n\\n---\\n\\n![](assets/image-20250901230608827.png)\\n\\n---\\n\\n那么最后我就拿着这段代码喂给ai，结果一次就把功能实现完毕了 ！\\n\\n![](assets/image-20250901230902442.png)\\n\\n\\n\\n---\\n\\n## 最终效果\\n\\n![](assets/PixPin_2025-09-01_23-10-11.gif)\\n\\n## 知识库\\n\\n1. ima 知识库 \\n\\n   > 【ima知识库】鸿蒙应用知识库 API20 https://ima.qq.com/wiki/?shareId=b0d462ae618a0fefb5b714565cad3dd4a60411a435d5f81db51670ffb2ff3ad7\\n\\n2. 扫码使用\\n\\n   ![](assets/zhiuik.png)\\n\\n\\n\\n## 以往文章\\n\\n\\n\\n- [懂你的HarmonyOS知识库更新了，已经来到10970个文档了](https://mp.weixin.qq.com/s/sMd0CGe54T2Eya8dPaEn2A)\\n- [最新 HarmonyOS API 20 知识库 重磅推出](https://mp.weixin.qq.com/s/tmchdy91UKmAtwwJr-PQ-A)\\n\\n\\n\\n\\n\\n## 近期活动\\n\\n最近想要考取HarmonyOS基础或高级证书的同学，可以点击这个链接[加入我的班级](https://developer.huawei.com/consumer/cn/training/classDetail/7e230b074eaa41c587c71c1d1a9a6514?type=1%3Fha_source%3Dhmosclass&ha_sourceId=89000248)，考取成功有机会获得鸿蒙礼盒一份。\\n\\n![](assets/image-20250822223258675.png)\\n\\n\\n\\n## 联系我\\n\\n可以加我微信，带你了解更多HarmonyOS相关的资讯。\\n\\n![](assets/wanshaoweixin.jpg)"}'),_={name:"鸿蒙开发技巧/HarmonyOS 鸿蒙应用开发  AI的bug AI来修复/HarmonyOS 鸿蒙应用开发  AI的bug AI来修复.md"};function A(I,a,f,q,y,P){return s(),e("div",null,[...a[0]||(a[0]=[t("",39)])])}const x=n(_,[["render",A]]);export{k as __pageData,x as default};
